<!DOCTYPE html>
<html>
<head>
<title>Falling Sand</title>
<style>
body { background-color: #1e1e1e; color: #eee; font-family: sans-serif; }
#controls { display: flex; gap: 20px; margin-bottom: 20px; }
button { padding: 10px 20px; border: none; background-color: #333; color: #eee; cursor: pointer; border-radius: 5px; }
#canvas { display: block; center-block; margin: 0 auto; }
</style>
</head>
<body>

<div id="controls">
  <button id="mat-sand">Sand</button>
  <button id="mat-water">Water</button>
  <button id="mat-wall">Wall</button>
  <button id="mat-acid">Acid</button>
  <button id="mat-empty">Empty (Eraser)</button>
  <button id="clear">Clear</button>
</div>

<canvas id="canvas" width="800" height="600"></canvas>

<script>
const w = 80;
const h = 60;
const cellSize = 20; // pixels per cell
let grid = [];
let isDragging = false;
let lastX, lastY;
let selectedMaterial = "sand";


function init() {
  grid = Array(h).fill(null).map(() => Array(w).fill("empty"));
  document.getElementById("canvas").width = w * cellSize;
  document.getElementById("canvas").height = h * cellSize;

  const ctx = document.getElementById("canvas").getContext("2d");
  draw();
}

function draw() {
  const ctx = document.getElementById("canvas").getContext("2d");
  ctx.clearRect(0, 0, w * cellSize, h * cellSize);

  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const material = grid[y][x];
      const colorMap = {
        "empty": "black",
        "sand": "yellow",
        "water": "blue",
        "wall": "gray",
        "acid": "red"
      };

      ctx.fillStyle = colorMap[material] || "white"; // Default to white if material is unknown
      ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
    }
  }
}


function tick(n) {
  for (let i = 0; i < n; i++) {
    simulate();
    draw();
  }
}

function simulate() {
  // Copy the grid to avoid modifying it during iteration.
  const newGrid = grid.map(row => [...row]);

  for (let y = h - 1; y >= 0; y--) {
    for (let x = 0; x < w; x++) {
      const currentMaterial = newGrid[y][x];
      if (currentMaterial === "empty") continue;

      let nextMaterial = currentMaterial;

      // Sand
      if (currentMaterial === "sand") {
        let canFall = true;
        if (y + 1 < h && newGrid[y + 1][x] !== "empty") canFall = false;

        if (canFall) {
          nextMaterial = "empty";
          newGrid[y][x] = "empty";
        } else {
            let direction = Math.random() < 0.5 ? -1 : 1;
            if (x + direction >= 0 && x + direction < w && newGrid[y][x + direction] !== "empty") {
                nextMaterial = "empty";
                newGrid[y][x] = "empty";
                newGrid[y][x + direction] = "sand";

            }
        }
      }
      // Water
      else if (currentMaterial === "water") {
        let canSpread = true;
        if (y + 1 >= h) canSpread = false;
        if(canSpread){
          let direction = Math.random() < 0.5 ? -1 : 1;
            if (x + direction >= 0 && x + direction < w && newGrid[y][x+direction] === "empty") {
                nextMaterial = "empty";
                newGrid[y][x] = "empty";
                newGrid[y][x + direction] = "water";

            }


        }



      }
      // Acid
      else if (currentMaterial === "acid") {
        let canDissolve = false;
        if (y + 1 < h && newGrid[y + 1][x] === "sand" || y + 1 < h && newGrid[y+1][x]=== "wall"){
            canDissolve = true;

        }
        if (x + 1 < w && newGrid[y][x + 1] === "sand" || x+1 <w && newGrid[y][x+1] === "wall") {
          canDissolve = true;
        }

        if(canDissolve){
             newGrid[y][x] = "empty";
           if (y + 1 < h && newGrid[y + 1][x] === "sand") {
                newGrid[y + 1][x] = "empty";
            }

            if(y+1<h && newGrid[y+1][x] === "wall"){
                  newGrid[y + 1][x] = "empty";
            }


              if (x + 1 < w && newGrid[y][x + 1] === "sand") {
                newGrid[y][x + 1] = "empty";
              }

             if(x+1<w && newGrid[y][x+1] ==="wall"){
                  newGrid[y][x + 1] = "empty";
            }



        }


      }

      // Walls - do nothing
      else {
          nextMaterial = currentMaterial;
      }
       grid[y][x] = nextMaterial;

    }
  }
}


document.getElementById("mat-sand").addEventListener("click", () => { selectedMaterial = "sand" });
document.getElementById("mat-water").addEventListener("click", () => { selectedMaterial = "water" });
document.getElementById("mat-wall").addEventListener("click", () => { selectedMaterial = "wall" });
document.getElementById("mat-acid").addEventListener("click", () => { selectedMaterial = "acid" });
document.getElementById("mat-empty").addEventListener("click", () => { selectedMaterial = "empty" });
document.getElementById("clear").addEventListener("click", () => {
  grid = Array(h).fill(null).map(() => Array(w).fill("empty"));
  draw();
});

canvas.addEventListener("mousedown", (e) => {
  isDragging = true;
  lastX = e.offsetX;
  lastY = e.offsetY;
});

canvas.addEventListener("mouseup", () => {
  isDragging = false;
});

canvas.addEventListener("mousemove", (e) => {
  if (!isDragging) return;
  const x = e.offsetX;
  const y = e.offsetY;

  const dx = x - lastX;
  const dy = y - lastY;

  lastX = x;
  lastY = y;


  const newX = Math.max(0, Math.min(w - 1, parseInt(x / cellSize)));
  const newY = Math.max(0, Math.min(h - 1, parseInt(y / cellSize)));

  grid[newY][newX] = selectedMaterial;
  draw();


});

init();

</script>

</body>
</html>
